function medicinePilotRace(array $f,array $jobs):array {
    $work=__DIR__.'/.medicine38-validation/pilot';if(!is_dir($work)){mkdir($work);}foreach(['ready1','ready2','go'] as $file){if(is_file($work.'/'.$file)){unlink($work.'/'.$file);}}
    $processes=[];foreach($jobs as $n=>$job){$job['configuration']=$f[6]->configuration;file_put_contents($work.'/job'.$n.'.json',json_encode($job,JSON_THROW_ON_ERROR));$processes[$n]=proc_open([PHP_BINARY,__FILE__,'worker',(string)$n],[0=>['pipe','r'],1=>['file',$work.'/out'.$n.'.json','w'],2=>['file',$work.'/err'.$n,'w']],$pipes);if(!is_resource($processes[$n])){throw new RuntimeException('Pilot worker startup failed');}fclose($pipes[0]);}
    $deadline=microtime(true)+20;while(!is_file($work.'/ready1')||!is_file($work.'/ready2')){if(microtime(true)>$deadline){throw new RuntimeException('Pilot barrier timed out');}usleep(10000);}file_put_contents($work.'/go','go');
    $results=[];foreach($processes as $n=>$process){medicineCheck(proc_close($process)===0,'Pilot worker failed; inspect isolated diagnostics');$results[]=json_decode(file_get_contents($work.'/out'.$n.'.json'),true,32,JSON_THROW_ON_ERROR);}medicineCheck(count(array_filter($results,fn($r)=>$r['status']==='ok'))===1);medicineCheck(count(array_filter($results,fn($r)=>$r['status']==='denied'))===1);return $results;
}
