medicineTest('fresh schema all Medicine constraints indexes FKs and immutable triggers',function()use($pdo,$source){
    preg_match_all('/CREATE TABLE `(kobi_medicine_[^`]+|medicine_[^`]+|health_medicine_identity_links|health_medicine_selected_ingredients)` \((.*?)\) ENGINE=/s',$source,$tables,PREG_SET_ORDER);medicineCheck(count($tables)===15);
    foreach($tables as $table){$actual=$pdo->query('SHOW CREATE TABLE `'.$table[1].'`')->fetch()['Create Table'];
        preg_match_all('/CONSTRAINT `([^`]+)`/',$table[2],$expected);preg_match_all('/CONSTRAINT `([^`]+)`/',$actual,$found);sort($expected[1]);sort($found[1]);medicineCheck($expected[1]===$found[1],$table[1].' constraints differ');
        preg_match_all('/(?:UNIQUE )?KEY `([^`]+)`/',$table[2],$expected);preg_match_all('/(?:UNIQUE )?KEY `([^`]+)`/',$actual,$found);
        medicineCheck(array_diff($expected[1],$found[1])===[],$table[1].' required index missing');
        preg_match_all('/CONSTRAINT `([^`]+)` FOREIGN KEY/',$table[2],$foreign);
        // InnoDB creates missing FK backing indexes under the constraint name.
        medicineCheck(array_diff($found[1],$expected[1],$foreign[1])===[],$table[1].' unexplained extra index');
    }
    medicineCheck((int)$pdo->query("SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='".MEDICINE_PILOT_DB."' AND TRIGGER_NAME LIKE 'medicine_%'")->fetchColumn()===12);
